import{_ as a,o as e,c as r,aj as d}from"./chunks/framework.m090XgxO.js";const m=JSON.parse('{"title":"场景示例","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":1788843575000}'),o={name:"examples/index.md"};function n(i,t,s,l,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="场景示例" tabindex="-1">场景示例 <a class="header-anchor" href="#场景示例" aria-label="Permalink to &quot;场景示例&quot;">​</a></h1><p>组件参考是一件一件看的：一页一个组件，一个示例一个知识点。这一册反过来——<strong>把十几件组件摆进同一屏</strong>，看它们凑在一起是不是一副样子。</p><p>一件组件单看总是对的。间距差一档、圆角差两像素、标题层级各写各的，只有在同框时才显形。所以这一册的每一页都是一整屏的界面，不是组件目录。</p><h2 id="收了哪几页" tabindex="-1">收了哪几页 <a class="header-anchor" href="#收了哪几页" aria-label="Permalink to &quot;收了哪几页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页</th><th>主要看什么</th><th>同框的组件</th></tr></thead><tbody><tr><td><a href="./admin-shell">后台壳</a></td><td>骨架、导航与头部一条线</td><td>布局 · 侧栏导航 · 面包屑 · 页头 · 工具条 · 角标 · 菜单 · 头像 · 提示 · 卡片 · 统计 · 分隔线 · 标签 · 按钮</td></tr><tr><td><a href="./form-page">表单页</a></td><td>一张值表喂七种控件</td><td>表单 · 字段 · 字段组 · 文本框 · 下拉 · 单选组 · 数字输入 · 标签输入 · 滑块 · 开关 · 复选框 · 警告条 · 页头</td></tr><tr><td><a href="./data-page">数据页</a></td><td>筛选、表格与三种状态</td><td>页头 · 文本框 · 下拉 · 分段控件 · 表格 · 标签 · 分页 · 空态 · 加载指示 · 提示 · 分隔线 · 按钮</td></tr><tr><td><a href="./chat-page">对话页</a></td><td>一条回复里的五件套</td><td>消息流 · 思考过程 · 工具调用 · 流式正文 · 代码视图 · 审批 · 提示输入框 · 头像 · 标签</td></tr></tbody></table><h2 id="这一册怎么写的" tabindex="-1">这一册怎么写的 <a class="header-anchor" href="#这一册怎么写的" aria-label="Permalink to &quot;这一册怎么写的&quot;">​</a></h2><ul><li><strong>是真组件，不是截图。</strong> 每页的预览就是当前这一版库跑出来的，点得动、切得了框架配色与深浅模式；源码在「查看代码」里，与预览同一个文件。</li><li><strong>不写裸色值。</strong> 页面里的每一处颜色都取<a href="./../guide/theme">设计令牌</a>，间距与圆角同理。换主题、换品牌色、切深色，这几页跟着一起变。</li><li><strong>不写时长与曲线。</strong> 动效节奏交给<a href="./../guide/motion">动效令牌</a>，示例里一个 <code>ms</code> 都不出现。</li><li><strong>数据是假的，接线是真的。</strong> 取数用定时器代替请求，其余的键盘、焦点、校验与状态流转都走组件本身。</li><li><strong>这一册目前只有 Vue 版。</strong> 顶部的框架切换器切到别的框架时，这几页会明说「还没有这一版」——组件参考那一册里每个组件都有 Vue 版，另外两家各自铺到哪一步见<a href="/adapters/vue">适配器</a>，场景页是这一册单独欠的账。</li></ul><p>想看某一件的完整契约，从<a href="./../components/">组件参考</a>进去；想知道这些页面为什么长这样，看<a href="./../guide/anatomy">核心概念</a>。</p>',8)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
